  if (Array.isArray(v)) return v.flatMap(addressesOf);
  if (isObject(v)) return v.address ? [String(v.address)] : v.value ? addressesOf(v.value) : v.text ? addressesOf(v.text) : [];
  return String(v)
    .split(/,(?=(?:[^"]*"[^"]*")*[^"]*$)/)
    .map((x) => (/<([^>]+)>/.exec(x)?.[1] ?? x).trim())
